//--------------------------------------------------------------------------------------------------

@MainActor func transient_PackageArc_selectionDisplay (
       _ prefs_selectionHiliteColor : NSColor,         
       _ self_xCenter : CanariLength,                  
       _ self_yCenter : CanariLength,                  
       _ self_radius : CanariLength,                   
       _ self_startAngle : CanariAngle,                
       _ self_arcAngle : CanariAngle,                  
       _ self_startTangent : CanariLength,             
       _ self_endTangent : CanariLength,               
       _ self_pathIsClosed : Bool,                     
       _ self_PackageObject_knobSize : Double
) -> EBShape {
//--- START OF USER ZONE 2
    let center = CanariPoint (x: self_xCenter, y: self_yCenter)
    let radius = self_radius
    let startTangentLength = self_startTangent
    let endTangentLength = self_endTangent
    let startAngle = self_startAngle
    let arcAngle = self_arcAngle
    var bp = BezierPath (
      arcWithTangentFromCenter: center,
      radius: radius,
      startAngle: startAngle,
      arcAngle: arcAngle,
      startTangentLength: startTangentLength,
      endTangentLength: endTangentLength,
      pathIsClosed: self_pathIsClosed
    )
    bp.lineWidth = 0.25
    bp.lineCapStyle = .round
    var shape = EBShape ()
    shape.add (stroke: [bp], prefs_selectionHiliteColor)
  //--- Add center knob
    shape.add (knobAt: center, knobIndex: PACKAGE_ARC_CENTER, .rect, .pt (self_PackageObject_knobSize))
  //--- Add radius knob
    var t = CanariAffinity.translating (center).rotating (by: startAngle + arcAngle / 2.0)
    let radiusKnob = t.transforming (x: radius)
    shape.add (knobAt: radiusKnob, knobIndex: PACKAGE_ARC_RADIUS, .diamond, .pt (self_PackageObject_knobSize))
  //--- Add start point knob
    t = CanariAffinity.translating (center).rotating (by: startAngle)
    let startPointKnob = t.transforming (x: radius)
    shape.add (knobAt: startPointKnob, knobIndex: PACKAGE_ARC_START_ANGLE, .diamond, .pt (self_PackageObject_knobSize))
  //--- Add end point knob
    t = CanariAffinity.translating (center).rotating (by: startAngle + arcAngle)
    let endPointKnob = t.transforming (x: radius)
    shape.add (knobAt: endPointKnob, knobIndex: PACKAGE_ARC_END_ANGLE, .diamond, .pt (self_PackageObject_knobSize))
  //---
    return shape
//--- END OF USER ZONE 2
}

